local ok,result=pcall(function() return np.select(condition,choices) end)
assert(ok==true,"ndarray-scalar-items/(2, 0)/int32: acceptance"..": "..tostring(result))
assert(type(result)=="userdata","ndarray-scalar-items/(2, 0)/int32: ndarray result")
eq(result:tolist(),{},"ndarray-scalar-items/(2, 0)/int32: result")
eq(result.shape,{0},"ndarray-scalar-items/(2, 0)/int32: result: shape")
eq(result.strides,{0},"ndarray-scalar-items/(2, 0)/int32: result: strides")
eq(result.dtype,"int32","ndarray-scalar-items/(2, 0)/int32: result: dtype")
cases=cases+1
end
end
chunk()
end
assert(cases==1961)
print('select104 differential: '..cases..' cases, '..checks..' checks passed')
